// The editor's static files, for a signed-in editor only: its theme script (read from `src/ui/`),
// the stylesheet and script `npm run build` writes to `dist/`, and the Editor row's logo.
//
// Every file is sent with an ETag made from its bytes. A page asks for it as `name?v=<version>`
// where the version is the same hash, so a changed file has a new address and a request that names
// the current version may be kept for a year (`immutable`); any other request is revalidated and
// answered 304 when nothing changed. Files are `private`: they are behind the session, and a
// shared cache must not hold them for someone who has not signed in.
import { createHash } from "node:crypto";
import { existsSync, readFileSync, statSync } from "node:fs";
import { extname } from "node:path";

import { EDITOR } from "./config.ts";

const SOURCE = new URL("./ui/", import.meta.url);
const DIST = new URL("../dist/", import.meta.url);

/** The files read from `src/ui/`; everything else comes from `dist/`. */
const SOURCES = ["theme.js"];

/** A built file's name: plain characters and a `.js` or `.css` ending, so no path leaves `dist/`. */
const BUILT = /^[A-Za-z0-9][A-Za-z0-9._-]*\.(js|css)$/;

const TYPES: Record<string, string> = {
  js: "text/javascript; charset=utf-8",
  css: "text/css; charset=utf-8",
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  webp: "image/webp",
  gif: "image/gif",
  avif: "image/avif",
  svg: "image/svg+xml",
};

interface Held {
  bytes: Buffer;
  type: string;
  version: string;
  stamp: number;
}

const held = new Map<string, Held>();

function locate(name: string): URL | null {
  if (SOURCES.includes(name)) return new URL(name, SOURCE);
  if (!BUILT.test(name)) return null;
  const built = new URL(name, DIST);
  return existsSync(built) ? built : null;
}

function load(name: string): Held | null {
  const where = name === "logo" ? logoPath() : locate(name);
  if (!where || !existsSync(where)) return null;
  const stamp = statSync(where).mtimeMs;
  const known = held.get(name);
  if (known && known.stamp === stamp) return known;
  const bytes = readFileSync(where);
  const type = TYPES[extname(String(where)).slice(1).toLowerCase()] ?? "application/octet-stream";
  const made = { bytes, type, version: createHash("sha256").update(bytes).digest("hex").slice(0, 12), stamp };
  held.set(name, made);
  return made;
}

/** Where the row's logo is kept: a path from the server's working directory, or null when none is named. */
function logoPath(): string | null {
  return EDITOR.logo === "" ? null : EDITOR.logo;
}

/** Whether `npm run build` has written the stylesheet and the script. */
export const isBuilt = (): boolean => existsSync(new URL("editor.css", DIST)) && existsSync(new URL("editor.js", DIST));

/** Whether the row names a logo that is there to be shown. */
export const hasLogo = (): boolean => load("logo") !== null;

/** The address of a file, with the version that makes it cacheable for good. */
export function assetUrl(name: string): string {
  const version = load(name)?.version;
  return `${EDITOR.basePath}/assets/${name}${version ? `?v=${version}` : ""}`;
}

/** Answers a request for one asset: the bytes, a 304 when the browser holds them, or a 404. */
export function serveAsset(name: string, request: Request): Response {
  const file = load(name);
  if (!file) return new Response("Not found.", { status: 404, headers: { "Content-Type": "text/plain" } });
  const etag = `"${file.version}"`;
  const headers = new Headers({
    "Content-Type": file.type,
    ETag: etag,
    "X-Content-Type-Options": "nosniff",
    "Cache-Control": new URL(request.url).searchParams.get("v") === file.version ? "private, max-age=31536000, immutable" : "private, no-cache",
  });
  if (name === "logo") headers.set("Content-Security-Policy", "sandbox");
  if (request.headers.get("if-none-match") === etag) return new Response(null, { status: 304, headers });
  return new Response(new Uint8Array(file.bytes), { headers });
}
